1	// Tập 7 · C4 · ĐOẠN E = S21–S24. N1 Month track BẢN C4 (c4kit.TrackC4): vách 15 năm làm đích → 180 ô đặt tới vách → (3/4) 14,6 ô trễ quá vách →
2	// mỗi tháng MỘT TỜ ĐÔ LA (nhỏ hơn ô) từ tay Tessa đặt lên mặt ô, ô bắt buộc giữ ink-muted quanh tờ, ô trễ rút hết → đường xong đúng ô 180 → bóng lịch
3	// 30 năm rút về vách, thanh mức bắt buộc đứng yên, một khoản bắt buộc tách lãi/gốc (lãi co lại) → một tờ nhấc lên (tháng khó, đường lui còn) → sóng
4	// mỗi tháng một tờ, 12 tờ của năm gom thành MỘT XẤP có khe → 4 ô trễ → chồng lãi nhỏ + khay tài khoản 12 tờ (đối trọng S24.2) → tờ đô la từ tay Tessa.
5	// Mốc giờ chỉ từ spine.json.
6	import { setup, figure, gesture, figTag, TrackC4, SplitBar, TRK, BUNDLE_TH, modeLook, followLight, chrome, SRC_SIM, label, seg2, dip,
7	  kf, show, pulse, C, ease, lin, mix, THREE, setOpacity } from '/episodes/ep007/world/c4kit.js';
8	import { TRACK_POSES } from '/episodes/ep007/world/c3kit.js';
9	import { Stack } from '/toolkit/factory/world/lib3d.js';
10	import { Bill } from '/episodes/ep007/world/obj7.js';
11	
12	const SEG = '/episodes/ep007/world/c4/e-s21-s24/';
13	
14	export async function boot(res) {
15	  // cQ: góc 3/4 (~40°) trước lưới — KHÔNG nhìn thẳng xuống lúc tấm trả thêm phủ (thấy cạnh tấm); vách thấp + trong mờ không che ô trễ;
16	  // Tessa, khoản bắt buộc tách hai phần (S22.2) và chồng lãi nhỏ (S24) đều trong khung
17	  const poses = { ...TRACK_POSES, cQ: { pos: [2.2, 5.4, 5.9], tgt: [2.5, 0.3, -1.9], fov: 52, chart: 1 } };
18	  const { S, D, G, cue, MV, st, O, renderer, scene, floor, key, CAM } = await setup(SEG, res, poses);
19	  const b = cue, X = S.x;
20	  const hm = figure(scene, { x: X.house[0], z: X.house[1], side: 1 }); hm.person.position.set(X.tessa[0], 0, X.tessa[1]);
21	  const track = TrackC4({ name: 'tessa' }); scene.add(track); const T = track.userData;
22	  // S22.1: thanh mức khoản bắt buộc (ink-muted, vật cố định) dọc mép trước 15 cột
23	  const rail = new THREE.Mesh(new THREE.BoxGeometry(1, 0.05, 0.06), new THREE.MeshStandardMaterial({ color: TRK.req, emissive: new THREE.Color(TRK.req), emissiveIntensity: 0.5, transparent: true }));
24	  rail.geometry.translate(0.5, 0, 0); rail.position.set(0, 0.03, track.frontZ() + 0.16); scene.add(rail); rail.userData.checks = { role: 'mark', key: 'required-level' };
25	  const bar = SplitBar({ x: X.bar[0], z: X.bar[1], h: 2.0 }); scene.add(bar);
26	  // S24.1: chồng lãi nhỏ (bó màu tiền — không phải warn: warn = giá của đường lui)
27	  const ist = Stack({ unitUsd: G.bundle_usd / BUNDLE_TH, bundleUsd: G.bundle_usd, w: 0.9, d: 0.6, maxUsd: 9000 }); ist.position.set(X.istack[0], 0, X.istack[1]); scene.add(ist);
28	  ist.userData.checks = { role: 'bar', series: 'yearly-extra-interest', key: 'yearly-extra-interest' };
29	  const IUSD = 8166;   // yearly_vs_monthly_interest (độ cao vật; nhãn qua claim)
30	  // S21.3 (C4 r2, ĐỔI LOẠI HÌNH lần 2 — tấm phủ của kit đọc thành "the tiles turn white"): phần trả thêm của mỗi tháng = MỘT TỜ ĐÔ LA (Bill của obj7,
31	  // vật tiền của S24.3/S25, sáng hơn chút) NHỎ HƠN Ô (62 % × 41 % cạnh ô) nằm TRÊN mặt ô; ô bắt buộc giữ ink-muted và thấy quanh tờ ở mọi khung
32	  // (tấm của kit tắt: drop = 0, cover = 0). Tờ rời tay Tessa, qua mép trước cột đầu rồi rải vào từng cột-năm (chạm ở land[c], một nốt mỗi cột).
33	  // S23: 12 tờ của năm trượt về ô thứ 12 thành MỘT XẤP 12 tờ có khe (BLP); màu lưới không đổi
34	  const BS = new THREE.Vector3(0.34, 1.8, 0.5), BH = 0.02 * BS.y, BLP = BH + 0.04;
35	  const glowBill = (g) => { g.traverse((m) => { if (m.isMesh) { m.material = m.material.clone(); m.material.emissive = m.material.color.clone().lerp(new THREE.Color('#FFFFFF'), 0.3); m.material.emissiveIntensity = 0.7; } }); return g; };
36	  const proto = glowBill(Bill({ name: 'extra-month' })), bills = proto.children.map((p) => {
37	    const im = new THREE.InstancedMesh(p.geometry.clone().translate(p.position.x, p.position.y, p.position.z), p.material, T.n);
38	    im.castShadow = im.receiveShadow = true; im.frustumCulled = false; scene.add(im); return im; });
39	  bills[0].userData.checks = { role: 'mark', series: 'tessa', key: 'track-tessa-extra-bills' };
40	  // S24.2: khay "tài khoản" (trước lưới, bên phải tên Tessa — C4 r2: không đè "Tessa · ILLUSTRATIVE") — 12 tờ đang chờ tới kỳ trả năm
41	  const tray = new THREE.Group(), trayBox = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.12, 0.62), new THREE.MeshStandardMaterial({ color: TRK.req, transparent: true, opacity: 0.35, depthWrite: false }));
42	  trayBox.position.y = 0.06; tray.add(trayBox);
43	  for (let k = 0; k < 12; k++) { const s = glowBill(Bill({ name: 'account' })); s.scale.set(1, 2, 1); s.position.set(0, 0.14 + k * 0.085, 0); tray.add(s); }
44	  tray.position.set(X.tray[0], 0, X.tray[1]); scene.add(tray); tray.userData.checks = { role: 'mark', key: 'account-tray' };
45	  const bill = Bill({ name: 'extra-dollar' }); scene.add(bill);
46	  const hand = [X.tessa[0] + 0.35, 0.7, X.tessa[1] + 0.2], dest = [X.house[0] + 0.1, 2.1, X.house[1] + 0.9];
47	  const lay = S.lay, land = S.land, NC = 15;
48	  const cl = (x) => Math.min(1, Math.max(0, x)), sm = (u) => u * u * (3 - 2 * u);
49	  const dep = (c) => land[0] - S.drop + 0.07 * c, via = [track.colX(0, -1) - 0.25, 0.95], zEnd = track.tileAt(T.cols - 1)[2];
50	  const blockTop = (c) => { const [x, y, z] = track.tileAt(c * T.cols + T.cols - 1); return [x, y + T.cols * BLP, z]; };
51	  const BM = new THREE.Matrix4(), BQ = new THREE.Quaternion(), BE = new THREE.Euler(), BP = new THREE.Vector3(), HIDE = new THREE.Matrix4().makeScale(0, 0, 0);
52	  // tờ tháng i: bay (Bezier tay → mép trước cột đầu → ô) rồi nằm trên ô; gathered(c), bob(i), lift = {i, a} như kit
53	  function setBills(t, gathered, bob, lift) {
54	    for (let i = 0; i < T.n; i++) {
55	      const c = Math.floor(i / T.cols), r = i % T.cols, t0 = dep(c);
56	      if (t < t0) { for (const m of bills) m.setMatrixAt(i, HIDE); continue; }
57	      const [x, yt, z] = track.tileAt(i), yR = yt + BH / 2 + 0.004, u = sm(lin(t, t0, land[c]));
58	      if (u < 1) {
59	        const v = 1 - u, zm = mix(hand[2], z, 0.5);
60	        BP.set(v * v * hand[0] + 2 * v * u * via[0] + u * u * x, v * v * hand[1] + 2 * v * u * via[1] + u * u * yR, v * v * hand[2] + 2 * v * u * zm + u * u * z);
61	        BE.set(0.95 * v, 0.25 * Math.sin(Math.PI * u), 0);
62	      } else {
63	        const k = T.cols - 1 - r, dl = 0.35 * k / (T.cols - 1), e = sm(cl((gathered(c) - dl) / (1 - dl))), y1 = yt + 0.004 + k * BLP + BH / 2;
64	        BP.set(x, yR + (y1 - yR) * e + 0.08 * Math.sin(Math.PI * e) + bob(i) + (lift.i === i ? 1.1 * lift.a : 0), z + (zEnd - z) * e); BE.set(0, 0, 0);
65	      }
66	      BM.compose(BP, BQ.setFromEuler(BE), BS); for (const m of bills) m.setMatrixAt(i, BM);
67	    }
68	    for (const m of bills) m.instanceMatrix.needsUpdate = true;
69	  }
70	
71	  function frame(t) {
72	    const pose = CAM.apply(t), cw = pose.chart, cam = CAM.cam;
73	    followLight(key, pose.tgt); modeLook(scene, floor, cw); gesture(hm, t, S.gestures);
74	    const late = t < S.clear_t ? kf(S.late21, t) : kf(S.late23, t);
75	    const curM = Math.min(179, Math.max(0, Math.floor(179 * lin(t, S.cursor[0], S.cursor[1])))), curOn = t > S.cursor[0] - 0.05 && t < S.cursor[1] + 0.4 ? 1 : 0;
76	    const gc = 15 * ease(t, b.b0.requires - 0.05, b.b0.requires + 1.2) * (1 - ease(t, b.b0.sooner - 0.05, b.b0.sooner + 0.6));
77	    const gathered = (c) => ease(t, S.gather[c][0], S.gather[c][1]),
78	      bob = (i) => { const u = (t - (S.wave[0] + (S.wave[1] - S.wave[0] - 0.3) * i / 179)) / 0.3; return (u > 0 && u < 1 ? 0.14 * Math.sin(Math.PI * u) : 0) + (i < 12 ? 0.12 * pulse(t, b.b3.once, 0.4) : 0); },
79	      lift = { i: S.lift.i, a: ease(t, S.lift.t[0] - 0.05, S.lift.t[0] + 0.45) * (1 - ease(t, S.lift.t[1], S.lift.t[1] + 0.5)) };
80	    setBills(t, gathered, bob, lift);
81	    // ô bắt buộc: ink-muted suốt (cover = 0, không tấm kit: drop = 0); loé "required" nhẹ (0,3) để lưới không đọc thành trắng
82	    track.set({ lit: kf(S.lit, t), late, cover: 0, drop: 0,
83	      flash: (c) => Math.min(1, pulse(t, lay[c] + 0.2, 0.6) + 0.3 * pulse(t, b.a2.required, 0.9) + curOn * (Math.floor(curM / 12) === c ? 0.7 : 0) + (c === 9 ? pulse(t, b.b2.later, 1.2) : 0)),
84	      ghost: gc, ghostA: gc > 0.01 ? 1 : 0,
85	      markA: ease(t, S.mark_t - 0.05, S.mark_t + 0.5) * (0.75 + 0.6 * pulse(t, b.a0.same, 1.0)) * (1 + 0.5 * pulse(t, b.b0.sooner, 1.0)),
86	      pulse: show(t, b.a1.late) * (1 - show(t, b.a1.late + 0.6)) + show(t, b.b5.four) * (1 - show(t, b.b5.four + 0.6)) });
87	    const rA = ease(t, b.b0.requires - 0.05, b.b0.requires + 0.6) * (1 - ease(t, MV.m_w22.t0, MV.m_w22.t0 + 0.4));
88	    rail.scale.x = Math.max(0.001, T.markX * lin(t, b.b0.requires, b.b0.requires + 0.8)); rail.visible = rA > 0.01; rail.material.opacity = rA;
89	    rail.material.emissiveIntensity = 0.5 + 1.0 * pulse(t, b.b0.stays, 1.0);
90	    const bA = show(t, b.b1.cut) * (1 - ease(t, MV.m_w22.t0, MV.m_w22.t0 + 0.4));
91	    bar.set({ share: S.share[curM], a: bA }); bar.visible = bA > 0.01;
92	    bar.children[1].material.emissiveIntensity = 0.35 + 0.8 * pulse(t, b.b1.principal, 1.0) + 0.4 * pulse(t, b.b1.fixed, 0.8);
93	    ist.set({ usd: IUSD * ease(t, b.b6.charges, b.b6.charges + 0.7) * (1 - ease(t, MV.m_w24.t0, MV.m_w24.t0 + 0.5)) });
94	    const tA = show(t, b.b7.account) * (1 - ease(t, MV.m_w24.t0, MV.m_w24.t0 + 0.5));
95	    setOpacity(tray, tA); trayBox.material.opacity = 0.35 * tA; tray.visible = tA > 0.01;
96	    // S24.3: tờ đô la hiện trong tay Tessa ("dollar"), bay lên về phía nhà rồi lơ lửng (câu hỏi mở)
97	    const a1 = show(t, b.b8.dollar), u = ease(t, b.b8.dollar + 0.2, b.b8.dollar + 1.8);
98	    bill.visible = a1 > 0.01; bill.scale.setScalar(Math.max(0.001, a1));
99	    bill.rotation.set(Math.PI / 2 * (0.35 + 0.65 * u), 0.3 * Math.sin(1.7 * t), 0);
100	    bill.position.set(mix(hand[0], dest[0], u), mix(hand[1], dest[1], u) + 0.6 * Math.sin(Math.PI * u) + 0.04 * Math.sin(2.2 * t), mix(hand[2], dest[2], u));
101	    renderer.render(scene, cam);
102	    // ---------------- lớp phủ
103	    const log = O.begin(t, cw, cam), ok = cw >= 0.95 ? 1 : 0; log.roi = {};
104	    dip(O, 1 - ease(t, 0, 0.4));
105	    figTag(O, hm);
106	    const sc = (x, y, z = 0) => O.toScreen(x, y, z);
107	    const [gx0, gy0] = sc(track.colX(0, -1), T.th, track.backZ()), [gx1, gy1] = sc(track.colX(T.years + 1, 1), T.th, track.frontZ());
108	    const [fx0, fy0] = sc(track.colX(0, -1), T.th, track.frontZ()), [mx, my] = sc(track.markWorldX(), 0, track.frontZ()), [mbx, mby] = sc(track.markWorldX(), 0.18, track.backZ());
109	    const grid = [Math.min(gx0, fx0), Math.min(gy0, mby) - 20, Math.max(gx1, mx), Math.max(fy0, gy1)];
110	    log.roi['a0.pay'] = grid; log.roi['a0.same'] = [Math.min(mx, mbx) - 30, mby - 30, Math.max(mx, mbx) + 30, my + 10];
111	    const [lx, ly] = sc(...track.tileAt(T.n)), [lx2] = sc(...track.tileAt(T.n + 12));
112	    log.roi['a1.doesnt'] = [lx - 60, ly - 60, lx2 + 60, ly + 260];
113	    // S21.2: hai nhãn của trạng thái "trễ" (tắt khi tấm trả thêm bắt đầu rơi)
114	    const old = b.a2.finish - 0.05;
115	    label(O, `pay ${D('pay15_now')} on the ${D('term_long')}: ${D('months_at_pay15_now')}`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.a1.ends, old),
116	      claims: ['pay15_now', 'term_long', 'months_at_pay15_now'] });
117	    log.roi['a1.ends'] = [300, 150, 1620, 230];
118	    // "about 15 months late" (mới ở C4) cạnh ô trễ; tắt khi ô trễ bắt đầu rút (cột đầu phủ xong)
119	    label(O, D('months_late_at_pay15_now'), 1810, ly - 80, { align: 'right', kind: 'number', color: C.warn, alpha: ok * show(t, b.a1.late, land[0] - 0.1), claims: ['months_late_at_pay15_now'] });
120	    log.roi['a1.late'] = [1200, ly - 130, 1810, ly - 60];
121	    // S21.3: tờ tiền từ tay Tessa tới cột đầu; nhãn hai dòng chỉ hiện khi không còn ô trễ nào
122	    { const [hx, hy] = sc(...hand); log.roi['a2.finish'] = [Math.min(hx, fx0) - 40, Math.min(hy, gy0) - 60, sc(track.colX(1, 1), 0, track.frontZ())[0] + 10, Math.max(hy, fy0) + 10]; }
123	    log.roi['a2.required'] = grid;
124	    const s7 = ok * show(t, b.a2.seven, b.b0.requires - 0.1) * (late <= 0 ? 1 : 0);
125	    label(O, `to finish in ${D('monthly_extra_months')}:`, 960, 205, { align: 'center', kind: 'number', alpha: s7, claims: ['monthly_extra_months'] });
126	    label(O, `${D('extra_month_about')} extra on top of the ${D('pay30_amt')} required`, 960, 268, { align: 'center', kind: 'number', alpha: s7, claims: ['extra_month_about', 'pay30_amt'] });
127	    log.roi['a2.seven'] = [300, 150, 1620, 290];
128	    // S22.1
129	    const w22 = MV.m_w22.t0 - 0.05;
130	    label(O, `required payment: stays ${D('pay30_amt')}`, 1120, 872, { align: 'center', kind: 'number', alpha: ok * show(t, b.b0.stays, w22), claims: ['pay30_amt'] });
131	    { const [r0x, r0y] = sc(0, 0.03, track.frontZ() + 0.16), [r1x] = sc(T.markX, 0.03, track.frontZ() + 0.16);
132	      log.roi['b0.requires'] = [r0x, r0y - 30, sc(track.colX(29, 1), 0, 0)[0], r0y + 30]; log.roi['b0.stays'] = [r0x, r0y - 30, r1x, r0y + 30]; }
133	    label(O, 'loan ends sooner', Math.min(1700, mbx), mby - 60, { align: 'center', kind: 'compare', alpha: ok * show(t, b.b0.sooner, w22) });
134	    log.roi['b0.sooner'] = [mbx - 40, mby - 30, Math.min(1920, sc(track.colX(29, 1), 0, 0)[0]), my + 10];
135	    // S22.2: khoản bắt buộc tách hai phần + tên hai phần (không số)
136	    { const [bx, by0] = sc(X.bar[0] + 0.3, 0, X.bar[1]), [, byS] = sc(X.bar[0] + 0.3, bar.h * S.share[curM], X.bar[1]), [, byT] = sc(X.bar[0] + 0.3, bar.h, X.bar[1]);
137	      const pa = ok * bA * show(t, b.b1.cut);
138	      // tên hai phần bên phải thanh, TRÊN tên "Tessa · ILLUSTRATIVE" (dưới chân Tessa, x ≤ ~600): gốc ngang đỉnh thanh, lãi ngay dưới
139	      label(O, 'principal', bx + 22, byT + 40, { kind: 'name', px: 48, alpha: pa * ease(t, b.b1.cut + 0.6, b.b1.cut + 1.2) });
140	      label(O, 'interest', bx + 22, Math.min(by0 - 20, byT + 118), { kind: 'name', px: 48, color: C.muted, alpha: pa });
141	      log.roi['b1.cut'] = [bx - 90, byT - 20, bx + 20, by0 + 10]; log.roi['b1.fixed'] = log.roi['b1.cut']; log.roi['b1.principal'] = [bx - 90, byT - 20, bx + 20, byS + 10]; }
142	    label(O, "next month's interest ↓, payment fixed", 960, 205, { align: 'center', kind: 'compare', alpha: ok * show(t, b.b1.interest, w22) });
143	    log.roi['b1.interest'] = [400, 150, 1520, 230];
144	    // S22.3 (thế giới): cột năm 10 loé, một tấm nhấc lên
145	    { const [x, y] = sc(...track.tileAt(S.lift.i)); log.roi['b2.later'] = [x - 60, y - 160, x + 60, y + 60]; log.roi['b2.wrong'] = log.roi['b2.later']; }
146	    // S23
147	    log.roi['b3.send'] = grid; { const [x, y] = sc(...blockTop(0)); log.roi['b3.once'] = [Math.min(gx0, fx0) - 10, y - 30, x + 60, fy0 + 10]; }
148	    log.roi['b4.extra'] = [Math.min(gx0, fx0), sc(...blockTop(7))[1] - 30, mx, my];
149	    const s24 = b.b7.verdict - 0.35;   // hai nhãn S23 giữ qua S24.1 (≥ 3 s đọc), nhường chỗ cho hai nhãn đối trọng S24.2
150	    label(O, `${D('yearly_lump')} (${D('yearly_lump_formula')})`, 960, 205, { align: 'center', kind: 'number', alpha: ok * show(t, b.b4.one, s24), claims: ['yearly_lump', 'yearly_lump_formula'] });
151	    log.roi['b4.one'] = [400, 150, 1520, 230];
152	    log.roi['b5.ends'] = [lx - 60, ly - 60, lx2 + 60, ly + 120];
153	    label(O, `ends in ${D('yearly_lump_months')}: ${D('yearly_lump_late')} than monthly`, 960, 268, { align: 'center', kind: 'number', alpha: ok * show(t, b.b5.four, s24),
154	      claims: ['yearly_lump_months', 'yearly_lump_late'] });
155	    log.roi['b5.four'] = [300, 215, 1620, 290];
156	    // S24.1–S24.2: chồng lãi nhỏ + nhãn; đối trọng (hai nhãn, khay viền nét đứt)
157	    const w24 = MV.m_w24.t0 - 0.05;
158	    { const [x, y] = sc(X.istack[0], IUSD / G.bundle_usd * BUNDLE_TH, X.istack[1]), [, y0] = sc(X.istack[0], 0, X.istack[1]);
159	      label(O, `${D('yearly_vs_monthly_interest')} more interest`, 1810, y - 40, { align: 'right', kind: 'number', alpha: ok * show(t, b.b6.about, w24), claims: ['yearly_vs_monthly_interest'] });
160	      log.roi['b6.charges'] = [x - 70, y - 20, x + 70, y0 + 10]; log.roi['b6.about'] = [1100, y - 90, 1810, y - 30]; }
161	    log.roi['b6.sits'] = [Math.min(gx0, fx0), sc(...blockTop(0))[1] - 30, mx, fy0];
162	    label(O, 'not a verdict on paying yearly', 960, 205, { align: 'center', kind: 'compare', alpha: ok * show(t, b.b7.verdict, w24) });
