117	export function WeekStrip(scene, values, { x0 = -9, width = 15, z = -3.2, depth = 0.5, tileH = 0.05, unit = 2.6 / 30000 } = {}) {
118	  const n = values.length, pitch = width / n;
119	  const geo = new THREE.BoxGeometry(pitch * 0.92, 1, depth); geo.translate(0, 0.5, 0);
120	  const mesh = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ roughness: 0.8, transparent: true, emissive: new THREE.Color('#000000') }), n);
121	  mesh.frustumCulled = false; mesh.castShadow = true; mesh.receiveShadow = true; scene.add(mesh);
122	  const M4 = new THREE.Matrix4(), col = new THREE.Color(), cM = new THREE.Color(C.muted), cW = new THREE.Color(C.warn), cI = new THREE.Color(C.ink), hide = new THREE.Matrix4().makeScale(0, 0, 0);
123	  for (let i = 0; i < n; i++) mesh.setColorAt(i, cM);
124	  mesh.userData.checks = { role: 'series', key: 'week-strip', series: 'weeks' };
125	  const api = { mesh, n, pitch, x0, z, xOf: (i) => x0 + (i + 0.5) * pitch,
126	    set({ grow = 1, rise = 0, lastA = 0, a = 1 } = {}) {
127	      const L = grow * (n + 120);
128	      for (let i = 0; i < n; i++) {
129	        const g = Math.min(1, Math.max(0, (L - i) / 120));
130	        if (g <= 0.001) { mesh.setMatrixAt(i, hide); continue; }
131	        const r = Math.min(1, Math.max(0, rise * 1.25 - 0.25 * i / n));
132	        const hgt = Math.max(0.001, mix(tileH, values[i] * unit, r) * g);
133	        M4.makeScale(1, hgt, 1).setPosition(api.xOf(i), 0, z); mesh.setMatrixAt(i, M4);
134	        col.copy(cM).lerp(cW, r); if (i === n - 1) col.lerp(cI, lastA);
135	        mesh.setColorAt(i, col);
136	      }
137	      mesh.instanceMatrix.needsUpdate = true; mesh.instanceColor.needsUpdate = true;
138	      mesh.material.opacity = a; mesh.visible = a > 0.005;
139	    } };
140	  api.set({ grow: 0 });
