145	// xếp mỗi tầng cols × rows bó → tổng lãi hàng trăm nghìn đô la vẫn vừa khung thường; phần trên cùng (warnFrom) tô warn; bó ≥ hideFrom không vẽ (đang
146	// bay). Gốc = tâm đáy. set({count (bó, thực), warnFrom, hideFrom, a}); posOf(k) = tâm bó k (thế giới); topY(count) = đỉnh tầng cao nhất
147	export function BundleTower(scene, { x, z = 0, n, cols = 3, rows = 3, bw = 0.9, bd = 0.6, gap = 0.04, name = 'tower' } = {}) {
148	  const cap = Math.ceil(n) + 1, th = BUNDLE_TH, per = cols * rows;
149	  const geo = new THREE.BoxGeometry(bw, th * 0.92, bd), mesh = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ roughness: 0.8, transparent: true }), cap);
150	  const strap = new THREE.InstancedMesh(new THREE.BoxGeometry(bw * 0.16, th * 0.94, bd * 1.02), new THREE.MeshStandardMaterial({ color: PALETTE.strap, roughness: 0.85, transparent: true }), cap);
151	  const g = new THREE.Group(); g.add(mesh, strap); g.position.set(x, 0, z); scene.add(g);
152	  mesh.castShadow = mesh.receiveShadow = true; mesh.frustumCulled = strap.frustumCulled = false;
153	  const M4 = new THREE.Matrix4(), col = new THREE.Color(), hide = new THREE.Matrix4().makeScale(0, 0, 0);
154	  for (let k = 0; k < cap; k++) mesh.setColorAt(k, col.set(PALETTE.bill));
155	  const local = (k) => { const L = Math.floor(k / per), c = k % per; return [(c % cols - (cols - 1) / 2) * (bw + gap), L * th + th / 2, (Math.floor(c / cols) - (rows - 1) / 2) * (bd + gap)]; };
156	  g.userData.checks = { role: 'bar', series: name, key: `tower-${name}` };
157	  g.set = ({ count = 0, warnFrom = Infinity, hideFrom = Infinity, a = 1 } = {}) => {
158	    for (let k = 0; k < cap; k++) {
159	      const frac = Math.min(1, Math.max(0, count - k));
160	      if (frac <= 0.001 || k >= hideFrom) { mesh.setMatrixAt(k, hide); strap.setMatrixAt(k, hide); continue; }
161	      const [lx, ly, lz] = local(k);
162	      M4.makeScale(1, frac, 1).setPosition(lx, ly - th * (1 - frac) / 2, lz); mesh.setMatrixAt(k, M4); strap.setMatrixAt(k, M4);
163	      mesh.setColorAt(k, col.set(k >= warnFrom ? PALETTE.warn : Math.floor(k / per) % 2 ? PALETTE.bill : PALETTE.bill2));
164	    }
165	    mesh.instanceMatrix.needsUpdate = strap.instanceMatrix.needsUpdate = true; mesh.instanceColor.needsUpdate = true;
166	    mesh.material.opacity = strap.material.opacity = a; g.visible = a > 0.005 && count > 0.001;
167	    g.userData.checks.value = +count.toFixed(2);
168	  };
169	  g.posOf = (k) => { const [lx, ly, lz] = local(k); return [x + lx, ly, z + lz]; };
170	  g.topY = (count) => (Math.floor(Math.max(0, count - 1e-6) / per) + 1) * th;
171	  g.halfW = (cols * (bw + gap) - gap) / 2;
172	  g.set({ count: 0 });
173	  return g;
174	}
