190	// ngoặc đứng (V6, nét lớp phủ): x, y0 (trên) → y1 (dưới), chân hướng trái (tick > 0 = về phía vật bên trái)
191	export function vbrace(O, x, y0, y1, color, a, lw = 6, tick = 16) {
192	  if (a <= 0.01) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.strokeStyle = color; c.lineWidth = lw;
193	  c.beginPath(); c.moveTo(x - tick, y0); c.lineTo(x, y0); c.lineTo(x, y1); c.lineTo(x - tick, y1); c.stroke(); c.restore();
194	}
195	// mở/kết đoạn: phủ nền tối dần (ranh giới đoạn; ident ở đoạn a). Vẽ TRƯỚC mọi chữ (chữ giữ tương phản)
196	export function dip(O, a) { if (a <= 0.005) return; const c = O.ctx; c.save(); c.globalAlpha = a; c.fillStyle = C.bg; c.fillRect(0, 0, 1920, 1080); c.restore(); }
197	
198	// ================================================================ V1 lưới phát lại (B10): 1.833 ô, cột = một năm (1991 … 2026, trái → phải = thời gian), hàng = tuần trong
199	// năm (tuần đầu năm ở trên). Tường đứng sau trục thời gian chung của đoạn c. set({fill, lastA, wave, a}): fill = số tuần đã hiện (thực, theo thứ
200	// tự thời gian); lastA: ô cuối (tuần của Tessa) sáng ink + to ×1,6; wave = chỉ số tuần đang loé (sóng "hỏi câu của cô ở mọi tuần trước", phải → trái)
201	export function WeekGrid(scene, weeks, { x0, width, y0 = 0.3, height = 4.5, z = -0.6, name = 'replay-grid' } = {}) {
202	  const n = weeks.length, Y0 = +weeks[0].slice(0, 4), ncol = +weeks[n - 1].slice(0, 4) - Y0 + 1, col = [], row = [];
203	  let yr = -1, k = 0; for (const w of weeks) { const y = +w.slice(0, 4) - Y0; if (y !== yr) { yr = y; k = 0; } col.push(y); row.push(k++); }
204	  const nrow = Math.max(...row) + 1, cw = width / ncol, ch = height / nrow;
205	  const mesh = new THREE.InstancedMesh(new THREE.BoxGeometry(cw * 0.86, ch * 0.76, 0.04), new THREE.MeshStandardMaterial({ roughness: 0.7, transparent: true }), n);
206	  mesh.frustumCulled = false; scene.add(mesh); mesh.userData.checks = { role: 'series', series: 'weeks', key: name };
207	  const M4 = new THREE.Matrix4(), c = new THREE.Color(), cE = new THREE.Color(C.grid), cM = new THREE.Color(C.muted), cI = new THREE.Color(C.ink), hide = new THREE.Matrix4().makeScale(0, 0, 0);
208	  const at = (i) => [x0 + (col[i] + 0.5) * cw, y0 + height - (row[i] + 0.5) * ch, z];
209	  const api = { mesh, n, at, cw, ch, x0, z, top: y0 + height,
210	    box: (i) => { const [x, y] = at(i); return [[x - cw * 0.43, y - ch * 0.38, z], [x + cw * 0.43, y + ch * 0.38, z]]; },
211	    set({ fill = n, lastA = 0, wave = null, waveW = 60, a = 1 } = {}) {
212	      for (let i = 0; i < n; i++) {
213	        const f = Math.min(1, Math.max(0, fill - i));
214	        if (f <= 0.001 || a <= 0.005) { mesh.setMatrixAt(i, hide); continue; }
215	        const [x, y] = at(i), last = i === n - 1 ? lastA : 0, s = (0.4 + 0.6 * f) * (1 + 0.6 * last);
216	        M4.makeScale(s, s, 1).setPosition(x, y, z); mesh.setMatrixAt(i, M4);
217	        const wv = wave == null ? 0 : Math.max(0, 1 - Math.abs(i - wave) / waveW);
218	        c.copy(cE).lerp(cM, f).lerp(cI, Math.max(last, 0.85 * wv)); mesh.setColorAt(i, c);
219	      }
220	      mesh.instanceMatrix.needsUpdate = true; if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
221	      mesh.material.opacity = a; mesh.visible = a > 0.005 && fill > 0;
222	    } };
223	  api.set({ fill: 0 });
224	  return api;
225	}
226	
227	// ================================================================ W2 hàng chồng theo tuần (B13–B20): 1.833 cột mảnh, cao = giá đường lui của tuần (extra_total) theo CÙNG
228	// thang của bó the stack (unit = BUNDLE_TH / bundle_usd → cột của tuần Tessa cao đúng bằng 15 bó). Gốc = mặt sàn. set({grow, rise, lit, hi, dx, a}):
229	// grow = phần tuần (trái → phải) đã mọc; rise ∈ [0,1] hệ số chiều cao; lit(i) ∈ [0,1] độ sáng (warn ↔ warn tối); hi(i) ∈ [0,1] → ink; dx(i) dời ngang (tách thập kỷ)
230	export function WeekRow(scene, values, { x0, width, z = 0, depth = 0.3, unit, name = 'weekly-stacks' } = {}) {
231	  const n = values.length, pitch = width / n;
232	  const geo = new THREE.BoxGeometry(pitch * 0.92, 1, depth); geo.translate(0, 0.5, 0);
233	  const mesh = new THREE.InstancedMesh(geo, new THREE.MeshStandardMaterial({ roughness: 0.8, transparent: true }), n);
234	  mesh.frustumCulled = false; mesh.castShadow = true; scene.add(mesh); mesh.userData.checks = { role: 'series', series: 'extra_total', key: name };
235	  const M4 = new THREE.Matrix4(), c = new THREE.Color(), cW = new THREE.Color(C.warn), cD = new THREE.Color('#4A3F2A'), cI = new THREE.Color(C.ink), hide = new THREE.Matrix4().makeScale(0, 0, 0);
236	  const api = { mesh, n, pitch, x0, z, unit, h: (i) => values[i] * unit, xOf: (i, dx = 0) => x0 + (i + 0.5) * pitch + dx,
237	    // span(i) → [y0, y1] thay chiều cao mặc định (cột "khoảng chênh" của đoạn c: từ hai đường lãi xuống trục, rồi thành chồng); color(i, c) tô thẳng
238	    set({ grow = 1, rise = 1, lit = null, hi = null, dx = null, span = null, color = null, a = 1 } = {}) {
239	      const L = grow * (n + 90);
240	      for (let i = 0; i < n; i++) {
241	        const g = Math.min(1, Math.max(0, (L - i) / 90)) * rise;
242	        if (g <= 0.001 || a <= 0.005) { mesh.setMatrixAt(i, hide); continue; }
243	        const [y0, y1] = span ? span(i) : [0, values[i] * unit];
244	        M4.makeScale(1, Math.max(0.001, (y1 - y0) * g), 1).setPosition(api.xOf(i, dx ? dx(i) : 0), y0, z); mesh.setMatrixAt(i, M4);
245	        if (color) color(i, c); else { c.copy(cD).lerp(cW, lit ? lit(i) : 1); if (hi) c.lerp(cI, hi(i)); }
246	        mesh.setColorAt(i, c);
247	      }
248	      mesh.instanceMatrix.needsUpdate = true; if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
249	      mesh.material.opacity = a; mesh.visible = a > 0.005 && grow > 0;
250	    } };
251	  api.set({ grow: 0 });
252	  return api;
253	}
254	
255	// ================================================================ N1 Month track, BẢN C4 (S21–S24) — sửa lỗi CHÍNH của C3 (C3-answer câu 1: "lớp trả thêm không thấy bằng hình")
256	// bằng ĐỔI LOẠI HÌNH (không chỉ độ sáng): lớp trả thêm là TẤM NỔI có độ dày (0,075 ≈ ô bắt buộc), phủ 86 % mặt ô, cạnh bên thấy được từ góc 3/4,
257	// phát quang ink; mỗi cột-năm có tấm RƠI từ trên cao xuống (drop[c] ∈ [0,1], một nốt mỗi cột); ô bắt buộc TỐI HẲN xuống (ink-muted → xám đậm) khi
258	// tấm của cột tới (cover[c]) → tương phản tấm sáng / ô tối. Gom năm (S23): 12 tấm của cột trượt về ô thứ 12 và chồng thành khối 12 lớp CÓ KHE
259	// (SG = 0,03 giữa hai lớp → đếm được); màu lưới không đổi khi gom. Ô trễ (warn) to ×1,2 và cao ×2,5; vách 15 năm thấp (0,18) và trong mờ → không
260	// che ô trễ. Bóng lịch 30 năm (ghost): 15 cột mờ quá vách = phần khoản 30 năm còn chạy nếu chỉ trả mức bắt buộc (S22.1 "ends sooner").
261	export const TRK = { req: '#9AA4B2', dark: '#343A44', warn: '#F2B441', ink: '#F2F4F7', empty: '#2A303B' };
262	export function TrackC4({ n = 180, cols = 12, spare = 2, tile = 0.34, gap = 0.08, th = 0.07, slab = 0.075, SG = 0.03, SF = 0.86, DROP = 1.3, name = 'tessa' } = {}) {
263	  const g = new THREE.Group(), pitch = tile + gap, years = Math.ceil(n / cols), nmax = n + spare * cols;
264	  const mat = (c, o = {}) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.8, transparent: true, ...o });
265	  const tiles = new THREE.InstancedMesh(new THREE.BoxGeometry(tile, th, tile), mat('#FFFFFF'), nmax);
266	  const slabs = new THREE.InstancedMesh(new THREE.BoxGeometry(tile * SF, slab, tile * SF), mat(TRK.ink, { emissive: new THREE.Color(TRK.ink), emissiveIntensity: 0.85 }), n);
267	  const ghost = new THREE.InstancedMesh(new THREE.BoxGeometry(tile, 0.014, tile), mat(TRK.req, { opacity: 0.3, depthWrite: false }), n);
268	  for (const m of [tiles, slabs]) { m.castShadow = m.receiveShadow = true; m.frustumCulled = false; g.add(m); }
269	  ghost.frustumCulled = false; g.add(ghost);
270	  const markX = years * pitch - gap / 2, depth = cols * pitch - gap;
271	  const mark = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.18, depth + 0.5), mat(TRK.req, { emissive: new THREE.Color(TRK.req), emissiveIntensity: 0.4, depthWrite: false }));
272	  mark.position.set(markX, 0.09, -depth / 2 + tile / 2); g.add(mark);
273	  const pos = (i) => [Math.floor(i / cols) * pitch + tile / 2, -(i % cols) * pitch];
274	  const M = new THREE.Matrix4(), col = new THREE.Color(), K = { req: new THREE.Color(TRK.req), dark: new THREE.Color(TRK.dark), warn: new THREE.Color(TRK.warn), ink: new THREE.Color(TRK.ink), empty: new THREE.Color(TRK.empty) };
275	  const hide = new THREE.Matrix4().makeScale(0, 0, 0), cl = (x) => Math.min(1, Math.max(0, x)), sm = (u) => u * u * (3 - 2 * u);
276	  tiles.userData.checks = { role: 'mark', series: name, key: `track-${name}-tiles` };
277	  slabs.userData.checks = { role: 'mark', series: name, key: `track-${name}-extra` };
278	  mark.userData.checks = { role: 'mark', series: name, key: `track-${name}-mark` };
279	  g.userData = { n, cols, pitch, tile, th, years, nmax, markX, depth, slab, SG };
280	  const zEnd = pos(cols - 1)[1], arr = (v, c) => (Array.isArray(v) ? v[c] || 0 : typeof v === 'function' ? v(c) : cl(v - c));
281	  // lit, late: như obj7 (số ô thực); flash/cover/drop/gathered: mảng theo cột (hoặc số thực "số cột từ trái"); lift = {i, a}: tấm tháng i nhấc lên (S22.3);
282	  // bob(i) → độ nảy của tấm tháng i (S23: sóng "mỗi tháng một lớp"); ghost = số cột bóng 30 năm (thực), ghostA; markA
283	  g.set = ({ lit = n, late = 0, flash = 0, cover = 0, drop = 0, gathered = 0, lift = null, bob = null, ghost: gc = 0, ghostA = 0, markA = 1, pulse = 0 } = {}) => {
284	    for (let i = 0; i < nmax; i++) {
285	      const [x, z] = pos(i), isLate = i >= n, c = Math.floor(i / cols), a = isLate ? cl(late - (i - n)) : cl(lit - i);
286	      if (a <= 0.002) { tiles.setMatrixAt(i, hide); continue; }
287	      if (isLate) { M.makeScale(1.2, 2.5, 1.2).setPosition(x, th * 2.5 / 2, z); col.copy(K.empty).lerp(K.warn, a * (0.85 + 0.15 * pulse)); }
288	      else { M.makeScale(1, a, 1).setPosition(x, th * a / 2, z); col.copy(K.req).lerp(K.dark, arr(cover, c)).lerp(K.ink, 0.8 * arr(flash, c)); }
289	      tiles.setMatrixAt(i, M); tiles.setColorAt(i, col);
290	    }
291	    for (let i = 0; i < n; i++) {
292	      const c = Math.floor(i / cols), r = i % cols, d = arr(drop, c) * cl(lit - i), [x, z] = pos(i);
293	      if (d <= 0.002) { slabs.setMatrixAt(i, hide); continue; }
294	      const k = cols - 1 - r, dl = 0.35 * k / (cols - 1), e = sm(cl((arr(gathered, c) - dl) / (1 - dl))), fall = sm(d);
295	      const y0 = th + slab / 2 + 0.004, y1 = th + 0.004 + k * (slab + SG) + slab / 2;
296	      let y = y0 + (y1 - y0) * e + 0.08 * Math.sin(Math.PI * e) + (1 - fall) * DROP;
297	      if (bob) y += bob(i); if (lift && lift.i === i) y += 1.1 * lift.a;
298	      M.makeScale(1, 1, 1).setPosition(x, y, z + (zEnd - z) * e); slabs.setMatrixAt(i, M);
299	    }
300	    for (let i = 0; i < n; i++) {
301	      const c = Math.floor(i / cols), a = cl(gc - c) * ghostA;
302	      if (a <= 0.002) { ghost.setMatrixAt(i, hide); continue; }
303	      const [x, z] = pos(i + n); M.makeScale(1, 1, 1).setPosition(x, 0.007, z); ghost.setMatrixAt(i, M);
304	    }
305	    for (const m of [tiles, slabs, ghost]) m.instanceMatrix.needsUpdate = true;
306	    if (tiles.instanceColor) tiles.instanceColor.needsUpdate = true;
307	    ghost.material.opacity = 0.3 * Math.min(1, ghostA); ghost.visible = ghostA > 0.01 && gc > 0;
308	    mark.material.opacity = 0.5 * markA; mark.visible = markA > 0.01;
309	    tiles.userData.checks.level = +Math.min(n, lit).toFixed(2); tiles.userData.checks.late = +late.toFixed(2);
310	  };
311	  g.blockTop = (c) => { const [x, z] = pos(c * cols + cols - 1); return [g.position.x + x, g.position.y + th + cols * (slab + SG), g.position.z + z]; };
312	  g.tileAt = (i) => { const [x, z] = pos(i); return [g.position.x + x, g.position.y + th, g.position.z + z]; };
313	  g.colX = (c, side = 0) => g.position.x + c * pitch + (side < 0 ? 0 : side > 0 ? tile : tile / 2);
314	  g.frontZ = () => g.position.z + tile / 2;
315	  g.backZ = () => g.position.z - (cols - 1) * pitch - tile / 2;
316	  g.markWorldX = () => g.position.x + markX;
317	  g.set({});
318	  return g;
319	}
320	
321	// ================================================================ S22.2 một khoản trả bắt buộc tách hai phần (lãi dưới, ink-muted đậm · gốc trên, ink): tổng cao CỐ ĐỊNH
322	// (khoản bắt buộc không đổi), phần lãi co lại theo tháng khi trả thêm → "next month's interest ↓, payment fixed". set({share, a}) share = phần lãi ∈ [0,1]
323	export function SplitBar({ x, z, h = 2.0, w = 0.55, d = 0.4 } = {}) {
324	  const g = new THREE.Group(), mk = (c, e) => new THREE.Mesh(new THREE.BoxGeometry(w, 1, d), new THREE.MeshStandardMaterial({ color: c, roughness: 0.7, transparent: true, emissive: new THREE.Color(c), emissiveIntensity: e }));
325	  const lo = mk(TRK.dark, 0.05), hi = mk(TRK.ink, 0.35); lo.castShadow = hi.castShadow = true; g.add(lo, hi); g.position.set(x, 0, z);
326	  lo.userData.checks = { role: 'bar', series: 'interest-part', key: 'split-interest' }; hi.userData.checks = { role: 'bar', series: 'principal-part', key: 'split-principal' };
327	  g.h = h;
328	  g.set = ({ share = 0.9, a = 1 } = {}) => {
329	    const hl = Math.max(0.001, h * share), hh = Math.max(0.001, h - hl);
330	    lo.scale.y = hl; lo.position.y = hl / 2; hi.scale.y = hh; hi.position.y = hl + hh / 2;
331	    setOpacity(g, a); lo.userData.checks.value = +share.toFixed(3);
332	  };
333	  g.set({ a: 0 });
334	  return g;
335	}
336	
337	// ================================================================ cảnh KHUNG cho đoạn chưa dựng (lượt 2): Tessa + nhà đứng yên, lớp bắt buộc
338	export async function stubScene(seg, res) {
339	  const poses = { w: { pos: [-3.4, 2.2, 7.6], tgt: [-0.6, 0.8, 0], fov: 35, chart: 0 } };
340	  const { S, st, O, renderer, scene, floor, CAM } = await setup(seg, res, poses);
341	  const hm = figure(scene, { x: 0 });
342	  function frame(t) {
343	    const pose = CAM.apply(t), cam = CAM.cam; modeLook(scene, floor, pose.chart); gesture(hm, t, S.gestures || []);
344	    renderer.render(scene, cam);
345	    const log = O.begin(t, pose.chart, cam); log.roi = {};
346	    figTag(O, hm); chrome(O);
347	    st.compose(); log.camMoving = CAM.moving(t); return log;
348	  }
349	  return { canvas: st.out, frame };
350	}
351	
352	export { C, CK, ease, lin, mix, rgba, THREE, Stack, setOpacity, PALETTE, home, nameTag, theStack, stackSet, BUNDLE_TH, label, brace, modeLook, FIG };
