    { const [bx, by0] = sc(X.bar[0] + 0.3, 0, X.bar[1]), [, byS] = sc(X.bar[0] + 0.3, bar.h * S.share[curM], X.bar[1]), [, byT] = sc(X.bar[0] + 0.3, bar.h, X.bar[1]);
