  const rail = new THREE.Mesh(new THREE.BoxGeometry(1, 0.05, 0.06), new THREE.MeshStandardMaterial({ color: TRK.req, emissive: new THREE.Color(TRK.req), emissiveIntensity: 0.5, transparent: true }));
