  const tray = new THREE.Group(), trayBox = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.12, 0.62), new THREE.MeshStandardMaterial({ color: TRK.req, transparent: true, opacity: 0.35, depthWrite: false }));
