        const g = gathered(c), k = T.cols - 1 - r, e = sm(cl((g - 0.5 * k / (T.cols - 1)) / 0.3)), dn = sm(cl((g - 0.8) / 0.2)), y1 = yt + 0.004 + k * BLP + BH / 2;
