  const poses = { ...TRACK_POSES, cQ: { pos: [2.2, 5.4, 5.9], tgt: [2.5, 0.3, -1.9], fov: 52, chart: 1 },
    cU: { pos: [-0.2, 0.98, 1.12], tgt: [0.2, 0.17, -0.12], fov: 30, chart: 1 }, cW: { pos: [6.1, 3.0, 3.2], tgt: [6.4, 0.1, -1.3], fov: 40, chart: 1 } };
