  const BS = new THREE.Vector3(0.25 / 0.62, 3, 0.2 / 0.28), BH = 0.02 * BS.y, BLP = BH + 0.03, HOV = 0.3;
  const glowBill = (g) => { g.traverse((m) => { if (m.isMesh) { m.material = m.material.clone(); m.material.color.lerp(new THREE.Color('#8FE09E'), 0.45);
