63	    const [dx, dy] = O.toScreen(...door); log.roi['a0.costs'] = [dx - 90, dy - 70, dx + 90, dy + 50];
64	    const [tx, ty] = O.toScreen(...tag.top()); log.roi['a1.borrowing'] = [tx - 70, ty - 20, tx + 70, ty + 130];
65	    // S01: nhãn giá (hai dòng) hiện cùng lúc bó đầu chạm (5,94 s); nhãn khoản vay ("dollars"). Nhãn S01 tắt khi thẻ khoản vay đầu hiện (S02.1).
66	    // Vòng bố cục 1 (đạo diễn: giá đọc thành giá của khoản vay vì nằm ngay dưới nhãn khoản vay, cùng cột với tấm giấy vay): mỗi nhãn neo VẬT của
67	    // nó bằng dây dẫn và đứng ở hai phía khác nhau — giá: khối trên-phải CHỒNG, dây xuống đỉnh chồng; khoản vay: dòng trên-trái, dây xuống tấm giấy
