      seg2(O, 96, 1024, 96 + w1, 1024, C.ink, 0.9 * show(t, b.a5.only, b.a6.say), 4); seg2(O, 96 + w0, 1024, 96 + wAll, 1024, C.ink, 0.9 * show(t, b.a5.history, b.a6.say), 4);
