  bar15.position.set(X.bar15, 0, 0); bar30.position.set(X.bar30, 0, 0); scene.add(bar15, bar30);
  const top15 = G.pay15 * SCALE, top30 = G.pay30 * SCALE, sliver = (G.pay30on15 - G.pay15) * SCALE;
