    const lxC = (b15x0 + b30x1) / 2;
    label(O, `fallback: ${D('fallback_gap_now')} lower`, lxC, y15 - 135, { align: 'center', kind: 'number', alpha: ok * show(t, b.b3.six, s5), color: '#7FD8C4', claims: ['fallback_gap_now'] });
